{{-- Existing summary IDs remain connected to LoadCashiersReportSummary(). --}}
<section class="fuel-report-stats" aria-label="Cashier report totals">
    <article class="fuel-report-stat"><div class="fuel-report-stat-label">Total sales <i class="bi bi-arrow-up-right" aria-hidden="true"></i></div><div class="fuel-report-stat-value">₱<span id="total_sales">0.00</span></div><p>Recorded sales for this shift</p></article>
    <article class="fuel-report-stat"><div class="fuel-report-stat-label">Cash on hand <span aria-hidden="true">₱</span></div><div class="fuel-report-stat-value">₱<span id="cash_on_hand">0.00</span></div><p>Cash recorded in this report</p></article>
    <article class="fuel-report-stat"><div class="fuel-report-stat-label">Non-cash payments <i class="bi bi-credit-card" aria-hidden="true"></i></div><div class="fuel-report-stat-value">₱<span id="total_non_cash_payment">0.00</span></div><p>Checks, cards, and digital payments</p></article>
    <article class="fuel-report-stat fuel-report-stat-variance"><div class="fuel-report-stat-label">Short / over <i class="bi bi-arrow-left-right" aria-hidden="true"></i></div><div class="fuel-report-stat-value">₱<span id="cash_short_or_over">0.00</span></div><p>Difference in recorded collections</p></article>
</section>
